        if decoded:
            period, motif = decoded
            # Prefer the orientation that places more marked cells on shared
            # diagonal stripes; tie-breaking is deterministic.
            indices = [r + c if diagonal == "sum" else c - r
                       for r, row in enumerate(grid)
                       for c, value in enumerate(row) if value]
            collisions = len(indices) - len(set(indices))
            candidates.append((collisions, len(motif), diagonal, period, motif))
    if not candidates:
        raise ValueError("no consistent diagonal stripe motif")
    _, _, diagonal, period, motif = max(candidates)
    return [[motif[((r + c) if diagonal == "sum" else (c - r)) % period]
